package io.github.finalparadox.item;
import com.google.common.collect.*;import net.minecraft.network.chat.Component;import net.minecraft.world.entity.*;import net.minecraft.world.entity.ai.attributes.*;import net.minecraft.world.item.*;import net.minecraft.world.item.enchantment.Enchantments;import net.minecraft.world.level.Level;import java.util.*;
public final class FrostscaleLeggingsItem extends ArmorItem{
 public static final String COOLDOWN_KEY="finalparadox.frostscale_cooldown";private final Multimap<Attribute,AttributeModifier>mods;
 public FrostscaleLeggingsItem(){super(ArmorMaterials.DIAMOND,Type.LEGGINGS,new Properties().stacksTo(1));ImmutableMultimap.Builder<Attribute,AttributeModifier>b=ImmutableMultimap.builder();b.putAll(super.getDefaultAttributeModifiers(EquipmentSlot.LEGS));b.put(Attributes.ATTACK_DAMAGE,new AttributeModifier(UUID.fromString("9e40055c-7956-4eca-ae4d-d61e7e126f93"),"Frostscale damage",.08,AttributeModifier.Operation.MULTIPLY_TOTAL));mods=b.build();}
 @Override public ItemStack getDefaultInstance(){ItemStack s=super.getDefaultInstance();prepare(s);return s;}@Override public void inventoryTick(ItemStack s,Level l,Entity e,int slot,boolean selected){prepare(s);super.inventoryTick(s,l,e,slot,selected);}private static void prepare(ItemStack s){s.getOrCreateTag().putBoolean("Unbreakable",true);s.getOrCreateTag().putInt("HideFlags",4);if(s.getEnchantmentLevel(Enchantments.ALL_DAMAGE_PROTECTION)<4)s.enchant(Enchantments.ALL_DAMAGE_PROTECTION,4);if(s.getEnchantmentLevel(Enchantments.BLAST_PROTECTION)<1)s.enchant(Enchantments.BLAST_PROTECTION,1);}@Override public Multimap<Attribute,AttributeModifier>getDefaultAttributeModifiers(EquipmentSlot slot){return slot==EquipmentSlot.LEGS?mods:super.getDefaultAttributeModifiers(slot);}
 @Override public void appendHoverText(ItemStack s,Level l,List<Component> t,TooltipFlag f){t.add(Component.empty());for(int i=1;i<=5;i++)t.add(Component.translatable("item.finalparadox.frostscale_leggings.lore."+i));t.add(Component.empty());t.add(Component.translatable("item.finalparadox.legendary"));}
}
